head.b:skin:
/*-----------------------------------------------

Blogger Template Style
Name:     Picture Window
Designer: Josh Peterson
URL:      www.noaesthetic.com
----------------------------------------------- */

/* Variable definitions
  ====================
  <Variable name="keycolor" description="Main Color" type="color" default="#1a222a" value="#992211"/>
  <Variable name="body.background" description="Body Background" type="background"
      color="$(body.background.color)" default="#111111 url(//themes.googleusercontent.com/image?id=1OACCYOE0-eoTRTfsBuX1NMN9nz599ufI1Jh0CggPFA_sK80AGkIr8pLtYRpNUKPmwtEa) repeat-x fixed top center" value="#dddddd url(https://www.despointesetdespixels.fr/docs/lcboathle/background-image-2024-2560px.jpg) no-repeat fixed top center"/>

  <Group description="Page Text" selector="body">
    <Variable name="body.font" description="Font" type="font"
        default="normal normal 15px Arial, Tahoma, Helvetica, FreeSans, sans-serif" value="normal normal 13px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
    <Variable name="body.text.color" description="Text Color" type="color" default="#333333" value="#454545"/>
  </Group>

  <Group description="Backgrounds" selector=".body-fauxcolumns-outer">
    <Variable name="body.background.color" description="Outer Background" type="color" default="#296695" value="#dddddd"/>
    <Variable name="header.background.color" description="Header Background" type="color" default="transparent" value="#ff4d52"/>
    <Variable name="post.background.color" description="Post Background" type="color" default="#ffffff" value="#ffffff"/>
  </Group>

  <Group description="Links" selector=".main-outer">
    <Variable name="link.color" description="Link Color" type="color" default="#336699" value="#ff4d52"/>
    <Variable name="link.visited.color" description="Visited Color" type="color" default="#6699cc" value="#ff4d52"/>
    <Variable name="link.hover.color" description="Hover Color" type="color" default="#33aaff" value="#02bcff"/>
  </Group>

  <Group description="Blog Title" selector=".header h1">
    <Variable name="header.font" description="Title Font" type="font"
        default="normal normal 36px Arial, Tahoma, Helvetica, FreeSans, sans-serif" value="normal normal 36px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
    <Variable name="header.text.color" description="Text Color" type="color" default="#ffffff"  value="#ffffff"/>
  </Group>

  <Group description="Tabs Text" selector=".tabs-inner .widget li a">
    <Variable name="tabs.font" description="Font" type="font"
        default="normal normal 15px Arial, Tahoma, Helvetica, FreeSans, sans-serif" value="normal bold 16px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
    <Variable name="tabs.text.color" description="Text Color" type="color" default="#ffffff" value="#ff4d52"/>
    <Variable name="tabs.selected.text.color" description="Selected Color" type="color" default="$(link.color)" value="#454545"/>
  </Group>

  <Group description="Tabs Background" selector=".tabs-outer .PageList">
    <Variable name="tabs.background.color" description="Background Color" type="color" default="transparent" value="#eeeeee"/>
    <Variable name="tabs.selected.background.color" description="Selected Color" type="color" default="transparent" value="#ffffff"/>
    <Variable name="tabs.separator.color" description="Separator Color" type="color" default="transparent" value="#cccccc"/>
  </Group>

  <Group description="Post Title" selector="h3.post-title, .comments h4">
    <Variable name="post.title.font" description="Title Font" type="font"
        default="normal normal 18px Arial, Tahoma, Helvetica, FreeSans, sans-serif" value="normal normal 18px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
  </Group>

  <Group description="Date Header" selector=".date-header">
    <Variable name="date.header.color" description="Text Color" type="color" default="$(body.text.color)" value="#454545"/>
  </Group>

  <Group description="Post" selector=".post">
    <Variable name="post.footer.text.color" description="Footer Text Color" type="color" default="#999999" value="#999999"/>
    <Variable name="post.border.color" description="Border Color" type="color" default="#dddddd" value="#dddddd"/>
  </Group>

  <Group description="Gadgets" selector="h2">
    <Variable name="widget.title.font" description="Title Font" type="font"
        default="bold normal 13px Arial, Tahoma, Helvetica, FreeSans, sans-serif" value="bold normal 13px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
    <Variable name="widget.title.text.color" description="Title Color" type="color" default="#888888" value="#ff4d52"/>
  </Group>

  <Group description="Footer" selector=".footer-outer">
    <Variable name="footer.text.color" description="Text Color" type="color" default="#cccccc" value="#ffffff"/>
    <Variable name="footer.widget.title.text.color" description="Gadget Title Color" type="color" default="#aaaaaa" value="#bbbbbb"/>
  </Group>

  <Group description="Footer Links" selector=".footer-outer">
    <Variable name="footer.link.color" description="Link Color" type="color" default="#99ccee" value="#0d2366"/>
    <Variable name="footer.link.visited.color" description="Visited Color" type="color" default="#77aaee" value="#ff4d52"/>
    <Variable name="footer.link.hover.color" description="Hover Color" type="color" default="#33aaff" value="#02bcff"/>
  </Group>

  <Variable name="content.margin" description="Content Margin Top" type="length" default="20px" value="30px"/>
  <Variable name="content.padding" description="Content Padding" type="length" default="0" value="15px"/>
  <Variable name="content.background" description="Content Background" type="background"
      default="transparent none repeat scroll top left" value="transparent url(//www.blogblog.com/1kt/transparent/white80.png) repeat scroll top left"/>
  <Variable name="content.border.radius" description="Content Border Radius" type="length" default="0" value="15px"/>
  <Variable name="content.shadow.spread" description="Content Shadow Spread" type="length" default="0" value="3px"/>

  <Variable name="header.padding" description="Header Padding" type="length" default="0" value="30px"/>
  <Variable name="header.background.gradient" description="Header Gradient" type="url"
      default="none" value="url(//www.blogblog.com/1kt/transparent/header_gradient_shade.png)"/>
  <Variable name="header.border.radius" description="Header Border Radius" type="length" default="0" value="10px"/>

  <Variable name="main.border.radius.top" description="Main Border Radius" type="length" default="20px" value="0"/>
  <Variable name="footer.border.radius.top" description="Footer Border Radius Top" type="length" default="0" value="10px"/>
  <Variable name="footer.border.radius.bottom" description="Footer Border Radius Bottom" type="length" default="20px" value="10px"/>
  <Variable name="region.shadow.spread" description="Main and Footer Shadow Spread" type="length" default="3px" value="0"/>
  <Variable name="region.shadow.offset" description="Main and Footer Shadow Offset" type="length" default="1px" value="0"/>

  <Variable name="tabs.background.gradient" description="Tab Background Gradient" type="url" default="none" value="url(//www.blogblog.com/1kt/transparent/tabs_gradient_shade.png)"/>
  <Variable name="tab.selected.background.gradient" description="Selected Tab Background" type="url"
      default="url(//www.blogblog.com/1kt/transparent/white80.png)" value="url(//www.blogblog.com/1kt/transparent/tabs_gradient_shade.png)"/>
  <Variable name="tab.background" description="Tab Background" type="background"
      default="transparent url(//www.blogblog.com/1kt/transparent/black50.png) repeat scroll top left" value="transparent none no-repeat scroll top left"/>

  <Variable name="tab.border.radius" description="Tab Border Radius" type="length" default="10px"  value="0"/>
  <Variable name="tab.first.border.radius" description="First Tab Border Radius" type="length" default="10px"  value="10px"/>
  <Variable name="tabs.border.radius" description="Tabs Border Radius" type="length" default="0"  value="10px"/>

  <Variable name="tabs.spacing" description="Tab Spacing" type="length" default=".25em" value="0"/>
  <Variable name="tabs.margin.bottom" description="Tab Margin Bottom" type="length" default="0" value="0"/>
  <Variable name="tabs.margin.sides" description="Tab Margin Sides" type="length" default="20px" value="0"/>

  <Variable name="main.background" description="Main Background" type="background"
      default="transparent url(//www.blogblog.com/1kt/transparent/white80.png) repeat scroll top left" value="transparent none repeat scroll top center"/>
  <Variable name="main.padding.sides" description="Main Padding Sides" type="length" default="20px" value="5px"/>

  <Variable name="footer.background" description="Footer Background" type="background"
      default="transparent url(//www.blogblog.com/1kt/transparent/black50.png) repeat scroll top left" value="transparent url(//www.blogblog.com/1kt/transparent/black50.png) repeat scroll top left"/>

  <Variable name="post.margin.sides" description="Post Margin Sides" type="length" default="-20px" value="-20px"/>
  <Variable name="post.border.radius" description="Post Border Radius" type="length" default="5px" value="10px"/>
  <Variable name="widget.title.text.transform" description="Widget Title Text Transform" type="string" default="uppercase" value="uppercase"/>

  <Variable name="mobile.background.overlay" description="Mobile Background Overlay" type="string"
  default="transparent none repeat scroll top left" value="transparent none repeat scroll top left"/> 

  <Variable name="startSide" description="Side where text starts in blog language" type="automatic" default="left"/>
  <Variable name="endSide" description="Side where text ends in blog language" type="automatic" default="right"/>
*/


/* AFFICHAGE SUR ECRAN ordinateur (> 1024px) */


/* Content
----------------------------------------------- */
body {
  font: $(body.font);
  color: $(body.text.color);
  background: $(body.background);
}



.content-outer {
  font-size: 90%;
}

a:link {
  text-decoration:none;
  color: $(link.color);
}

a:visited {
  text-decoration:none;
  color: $(link.visited.color);
}

a:hover {
  text-decoration:underline;
  color: $(link.hover.color);
}

.content-outer {
  background: $(content.background);

  -moz-border-radius: $(content.border.radius);
  -webkit-border-radius: $(content.border.radius);
  -goog-ms-border-radius: $(content.border.radius);
  border-radius: $(content.border.radius);

  -moz-box-shadow: 0 0 $(content.shadow.spread) rgba(0, 0, 0, .15);
  -webkit-box-shadow: 0 0 $(content.shadow.spread) rgba(0, 0, 0, .15);
  -goog-ms-box-shadow: 0 0 $(content.shadow.spread) rgba(0, 0, 0, .15);
  box-shadow: 0 0 $(content.shadow.spread) rgba(0, 0, 0, .15);

  margin: $(content.margin) auto;
}

.content-inner {
  padding: $(content.padding);
}

/* Header
----------------------------------------------- */
.navbar {
  display: none !important;
}

.header-outer {
  background: $(header.background.color) $(header.background.gradient) repeat-x scroll top left;
  _background-image: none;

  color: $(header.text.color);

  -moz-border-radius: $(header.border.radius);
  -webkit-border-radius: $(header.border.radius);
  -goog-ms-border-radius: $(header.border.radius);
  border-radius: $(header.border.radius);
}

.Header img, .Header #header-inner {
  -moz-border-radius: $(header.border.radius);
  -webkit-border-radius: $(header.border.radius);
  -goog-ms-border-radius: $(header.border.radius);
  border-radius: $(header.border.radius);
  width: stretch;
}

.header-inner .Header .titlewrapper,
.header-inner .Header .descriptionwrapper {
  padding-left: $(header.padding);
  padding-right: $(header.padding);
}

.Header h1 {
  font: $(header.font);
  text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.3);
}

.Header h1 a {
  color: $(header.text.color);
}

.Header .description {
  font-size: 130%;
}

/* Tabs
----------------------------------------------- */
.tabs-inner {
  margin: .5em $(tabs.margin.sides) $(tabs.margin.bottom);
  padding: 0;
}

.tabs-inner .section {
  margin: 0;
}

.tabs-inner .widget ul {
  padding: 0;

  background: $(tabs.background.color) $(tabs.background.gradient) repeat scroll bottom;

  -moz-border-radius: $(tabs.border.radius);
  -webkit-border-radius: $(tabs.border.radius);
  -goog-ms-border-radius: $(tabs.border.radius);
  border-radius: $(tabs.border.radius);
}

.tabs-inner .widget li {
  border: none;
}

.tabs-inner .widget li a {
  display: inline-block;

  padding: .5em 1em;
  margin-$endSide: $(tabs.spacing);

  color: $(tabs.text.color);
  font: $(tabs.font);

  -moz-border-radius: $(tab.border.radius) $(tab.border.radius) 0 0;
  -webkit-border-top-left-radius: $(tab.border.radius);
  -webkit-border-top-right-radius: $(tab.border.radius);
  -goog-ms-border-radius: $(tab.border.radius) $(tab.border.radius) 0 0;
  border-radius: $(tab.border.radius) $(tab.border.radius) 0 0;

  background: $(tab.background);

  border-$endSide: 1px solid $(tabs.separator.color);
}

.tabs-inner .widget li:first-child a {
  padding-$startSide: 1.25em;

  -moz-border-radius-top$startSide: $(tab.first.border.radius);
  -moz-border-radius-bottom$startSide: $(tabs.border.radius);
  -webkit-border-top-$startSide-radius: $(tab.first.border.radius);
  -webkit-border-bottom-$startSide-radius: $(tabs.border.radius);
  -goog-ms-border-top-$startSide-radius: $(tab.first.border.radius);
  -goog-ms-border-bottom-$startSide-radius: $(tabs.border.radius);
  border-top-$startSide-radius: $(tab.first.border.radius);
  border-bottom-$startSide-radius: $(tabs.border.radius);
}

.tabs-inner .widget li.selected a,
.tabs-inner .widget li a:hover {
  position: relative;
  z-index: 1;

  background: $(tabs.selected.background.color) $(tab.selected.background.gradient) repeat scroll bottom;
  color: $(tabs.selected.text.color);

  -moz-box-shadow: 0 0 $(region.shadow.spread) rgba(0, 0, 0, .15);
  -webkit-box-shadow: 0 0 $(region.shadow.spread) rgba(0, 0, 0, .15);
  -goog-ms-box-shadow: 0 0 $(region.shadow.spread) rgba(0, 0, 0, .15);
  box-shadow: 0 0 $(region.shadow.spread) rgba(0, 0, 0, .15);
}

/* Headings
----------------------------------------------- */
h2 {
  font: $(widget.title.font);
  text-transform: $(widget.title.text.transform);
  color: $(widget.title.text.color);
  margin: .5em 0;
}

/* Main
----------------------------------------------- */
.main-outer {
  background: $(main.background);

  -moz-border-radius: $(main.border.radius.top) $(main.border.radius.top) 0 0;
  -webkit-border-top-left-radius: $(main.border.radius.top);
  -webkit-border-top-right-radius: $(main.border.radius.top);
  -webkit-border-bottom-left-radius: 0;
  -webkit-border-bottom-right-radius: 0;
  -goog-ms-border-radius: $(main.border.radius.top) $(main.border.radius.top) 0 0;
  border-radius: $(main.border.radius.top) $(main.border.radius.top) 0 0;

  -moz-box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
  -webkit-box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
  -goog-ms-box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
  box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
}

.main-inner {
  padding: 15px $(main.padding.sides) 20px;
}

.main-inner .column-center-inner {
  padding: 0 0;
}

.main-inner .column-left-inner {
  padding-left: 0;
}

.main-inner .column-right-inner {
  padding-right: 0;
}

/* Posts
----------------------------------------------- */
h3.post-title {
  margin: 0;
  font: $(post.title.font);
}

.comments h4 {
  margin: 1em 0 0;
  font: $(post.title.font);
}

.date-header span {
  color: $(date.header.color);
}

.post-outer {
  background-color: $(post.background.color);
  border: solid 1px $(post.border.color);

  -moz-border-radius: $(post.border.radius);
  -webkit-border-radius: $(post.border.radius);
  border-radius: $(post.border.radius);
  -goog-ms-border-radius: $(post.border.radius);

  padding: 15px 20px;
  margin: 0 $(post.margin.sides) 20px;
}

.post-body {
  line-height: 1.4;
  font-size: 110%;
  position: relative;
}

/* Les images des posts ne dépassent plus et occupent la place disponible */
.post-body img{
  max-width: 100%;
  height:auto;
}

/* Les vidéos des posts ne dépassent plus et occupent la place disponible */
.post-body iframe{
  max-width: 100%;
}

.post-header {
  margin: 0 0 1.5em;

  color: $(post.footer.text.color);
  line-height: 1.6;
}

.post-footer {
  margin: .5em 0 0;

  color: $(post.footer.text.color);
  line-height: 1.6;
}

#blog-pager {
  font-size: 140%;
}

#comments .comment-author {
  padding-top: 1.5em;

  border-top: dashed 1px #ccc;
  border-top: dashed 1px rgba(128, 128, 128, .5);

  background-position: 0 1.5em;
}

#comments .comment-author:first-child {
  padding-top: 0;

  border-top: none;
}

.avatar-image-container {
  margin: .2em 0 0;
}

/* Comments
----------------------------------------------- */
.comments .comments-content .icon.blog-author {
  background-repeat: no-repeat;
  background-image: url(data:image/png;base64,);
}

.comments .comments-content .loadmore a {
  border-top: 1px solid $(link.hover.color);
  border-bottom: 1px solid $(link.hover.color);
}

.comments .continue {
  border-top: 2px solid $(link.hover.color);
}

/* Widgets
----------------------------------------------- */
.widget ul, .widget #ArchiveList ul.flat {
  padding: 0;
  list-style: none;
}

.widget ul li, .widget #ArchiveList ul.flat li {
  border-top: dashed 1px #ccc;
  border-top: dashed 1px rgba(128, 128, 128, .5);
}

.widget ul li:first-child, .widget #ArchiveList ul.flat li:first-child {
  border-top: none;
}

.widget .post-body ul {
  list-style: disc;
}

.widget .post-body ul li {
  border: none;
}

/* Footer
----------------------------------------------- */
.footer-outer {
  color:$(footer.text.color);
  background: $(footer.background);

  -moz-border-radius: $(footer.border.radius.top) $(footer.border.radius.top) $(footer.border.radius.bottom) $(footer.border.radius.bottom);
  -webkit-border-top-left-radius: $(footer.border.radius.top);
  -webkit-border-top-right-radius: $(footer.border.radius.top);
  -webkit-border-bottom-left-radius: $(footer.border.radius.bottom);
  -webkit-border-bottom-right-radius: $(footer.border.radius.bottom);
  -goog-ms-border-radius: $(footer.border.radius.top) $(footer.border.radius.top) $(footer.border.radius.bottom) $(footer.border.radius.bottom);
  border-radius: $(footer.border.radius.top) $(footer.border.radius.top) $(footer.border.radius.bottom) $(footer.border.radius.bottom);

  -moz-box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
  -webkit-box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
  -goog-ms-box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
  box-shadow: 0 $(region.shadow.offset) $(region.shadow.spread) rgba(0, 0, 0, .15);
}

.footer-inner {
  padding: 10px $(main.padding.sides) 20px;
}

.footer-outer a {
  color: $(footer.link.color);
}

.footer-outer a:visited {
  color: $(footer.link.visited.color);
}

.footer-outer a:hover {
  color: $(footer.link.hover.color);
}

.footer-outer .widget h2 {
  color: $(footer.widget.title.text.color);
}

/* Ancien système de gestion du responsive du thème pour mobile, désactivé et remplacé par un système de gestion du responsive basé sur des médias queries.
----------------------------------------------- */
/*
  html body.mobile {
    height: auto;
  }

  html body.mobile {
    min-height: 480px;
    background-size: 100% auto;
  }

  .mobile .body-fauxcolumn-outer {
    background: $(mobile.background.overlay);
  }

  html .mobile .mobile-date-outer, html .mobile .blog-pager {
    border-bottom: none;
    background: $(main.background);
    margin-bottom: 10px;
  }

  .mobile .date-outer {
    background: $(main.background);
  }

  .mobile .header-outer, .mobile .main-outer,
  .mobile .post-outer, .mobile .footer-outer {
    -moz-border-radius: 0;
    -webkit-border-radius: 0;
    -goog-ms-border-radius: 0;
    border-radius: 0;
  }

  .mobile .content-outer,
  .mobile .main-outer,
  .mobile .post-outer {
    background: inherit;
    border: none;
  }

  .mobile .content-outer {
    font-size: 100%;
  }

  .mobile-link-button {
    background-color: $(link.color);
  }

  .mobile-link-button a:link, .mobile-link-button a:visited {
    color: $(post.background.color);
  }

  .mobile-index-contents {
    color: $(body.text.color);
  }

  .mobile .tabs-inner .PageList .widget-content {
    background: $(tabs.selected.background.color) $(tab.selected.background.gradient) repeat scroll bottom;
    color: $(tabs.selected.text.color);
  }

  .mobile .tabs-inner .PageList .widget-content .pagelist-arrow {
    border-$startSide: 1px solid $(tabs.separator.color);
  }

*/
/* MISE EN FORME GENERALE */

nav#menu.menu a {
  display:block;
  padding:1em;
  text-decoration:none
  ;color:#FF4D52;
  border:none;
}

nav#menu.menu a:hover {
  background:#FFFFFF;color:#454545;
}

.menubtn {
  display:none;
}

nav#menu.menu ul,
nav#menu.menu ul li {
  list-style-type:none;
  padding:0;
  margin:0;
  background:#EEEEEE;
}
nav#menu.menu > ul > li > a {
  text-transform:uppercase;
}

nav#menu.menu .parent {
  position:relative;
}

nav#menu.menu > ul > li {
  display:block;
}

nav#menu.menu > ul {
  text-align:center;
}

.sousrubrique{
  visibility:hidden;
  position:absolute;
  top:100%;
  min-width:250px;
  left:0;
  z-index:-1;
  background:#EEEEEE;
  opacity:0;
  text-align:left;
  transform:translateY(-2em);
  transition:all .3s ease-in-out 0s,visibility 0s linear .3s,z-index 0s linear 10ms;
  -moz-box-shadow:3px 3px 5px 0 #656565;
  -webkit-box-shadow:3px 3px 5px 0 #656565;
  -o-box-shadow:3px 3px 5px 0 #656565;
  box-shadow:3px 3px 5px 0 #656565;
  filter:progid:DXImageTransform.Microsoft.Shadow(color=#656565, Direction=135, Strength=5)
}

nav#menu.menu > ul > li > ul > li {
  float:none;
}

nav#menu.menu ul,
nav#menu.menu ul li {
  overflow:visible;
}
nav#menu.menu ul li:hover .sousrubrique{
  visibility:visible;
  opacity:1;
  z-index:1;
  transform:translateY(0);
  transition-delay:0s,0s,.3s
}

head.b:template-skin:





/* Le contenu reste fixe à 1260px (Ancienne méthode) */
/*body {
  min-width: $(content.width);
}

.content-outer, .content-fauxcolumn-outer {
  min-width: $(content.width);
  max-width: $(content.width);
}*/

/* Le contenu s'adapte en fonction de la largeur disponible */
body {
  min-width: 0;
}

.content-outer, .content-fauxcolumn-outer {
  width: auto;
  min-width: 0;
  max-width: $(content.width);
}

.main-inner .columns {
  padding-left: $(main.column.left.width);
  padding-right: $(main.column.right.width);
}

.main-inner .fauxcolumn-center-outer {
  left: $(main.column.left.width);
  right: $(main.column.right.width);
}

.main-inner .fauxcolumn-left-outer {
  width: $(main.column.left.width);
}

.main-inner .fauxcolumn-right-outer {
  width: $(main.column.right.width);
}

.main-inner .column-left-outer {
  width: $(main.column.left.width);
  right: 100%;
  margin-left: -$(main.column.left.width);
}

.main-inner .column-right-outer {
  width: $(main.column.right.width);
  margin-right: -$(main.column.right.width);
}

#layout {
  min-width: 0;
}

#layout .content-outer {
  min-width: 0;
  width: 800px;
}

#layout .region-inner {
  min-width: 0;
  width: auto;
}



/* AFFICHAGE SUR ECRAN tablette (< 1024px) */

@media screen and (max-width : 1024px) and (min-width : 768px){

  /* Suppression des largeurs fixes héritées par le thème */
  body{
    min-width:0;
  }

  /* Masquage de la colonne de droite et de sa fauxcolumn*/
  .column-right-outer,
  .fauxcolumn-right-outer{
    display:none;
  }

  /* Réduction de la largeur de la colonne de gauche */
  .main-inner .column-left-outer,
  .main-inner .fauxcolumn-left-outer{
    width: 150px;
  } 

  /* Ajustement du décalage de la colonne pour conserver son alignement */
  .main-inner .column-left-outer {
    margin-left: -150px;
  }

  /* Le conteneur principal s'adapte désormais à la largeur disponible */
  .content-outer,
  .content-fauxcolumn-outer,
  .region-inner {
    min-width: 0;
    max-width: 100%;
    width: auto;
  }

  /* Réserve un espace de 150 px à gauche pour accueillir la colonne latérale réduite */
  .main-inner .columns{
    padding-left: 150px;
    padding-right: 0px;
  }

  /* Masque le compteur, les images et le widget HTML (numéro SIRET, etc.) afin d'alléger la colonne de gauche sur tablette */
  .column-left-outer .widget.Stats,
  .column-left-outer .widget.Image,
  .column-left-outer .widget.HTML{
    display:none; 
  }

  /* Mise en forme du bouton menu pour mobile */
  a.menubtn {
    display: inline-block;
    position: relative;
    padding: 0.5em 1.9em;
    text-decoration:none;
    color:#FF4D52;
    margin-top: 1em;
    border-radius: 3px;
    border: 1px solid #CCC;
    background: #EEEEEE;
  }

  /* Création de l'icône burger */
  .menubtn:before{
    content: "";
    position: absolute;
    left: 0.5em;
    top: 0.75em;
    width: 1em;
    height: 0.15em;
    background: black;
    box-shadow: 0 0.35em 0 0 black,0 0.7em 0 0 black;
  }

  /* Suppression des styles par défaut des listes pour personnaliser le menu */
  #menu ul,
  #menu ul li {
    list-style-type:none;
    padding:0;
    margin:0;
    text-transform:none;
  }

  /* Ajout d'un espacement entre le bouton menu et la liste de menu principale */
  #menu > ul {
    margin-top:10px;
  }

  /* Masquage du menu par défaut et ajout d'une animation pour l'ouverture */
  .js #menu{
    overflow: hidden;
    max-height: 0;
    transition: all 0.3s ease-out;
  }

  /* Affichage du menu et des sous-menus lorsque la classe .select est ajoutée */
  #menu.select, 
  .js #menu > ul ul.select {
    max-height: 55em;
    overflow: visible;
  }

  /* Mise en forme des liens et préparations du positionnement des indicateurs + / - avec la position: relative */
  #menu li a {
    color: #FF4D52;display: block;
    padding: 0.8em;
    border-bottom: 1px solid #EEE;
    position: relative;
  }

  /* Ajout de l'indicateur + lorsque le menu contenant une sous-menu ne possède pas la classe .select */
  #menu li.sousmenu > a:after {
    content: '+';
    position: absolute;
    top: 0;
    right: 3em;
    display: block;
    font-size: 1em;
    padding-top: 0.9em;
  }

  /* Ajout de l'indicateur - lorsque le menu contenant une sous-menu possède la classe .select */
  #menu li.sousmenu > a.select:after {
    content: "-";
    padding-top: 0.9em;
  }

  /* Le menu contenant un sous-menu qui est sélectionné s'allume pour indiquer à quel menu le sous-menu appartient */
  #menu li.sousmenu > a.select {
    background: #FFFFFF;
    color: #454545;
  }

  /* Les sous-rubrques sont affichées verticalement et leur texte est mis en majuscule */
  #menu li.sousmenu > ul li {
    text-transform:uppercase;
    float:none; 
  }

  /* Autorise les sous-menus à dépsser du conteneur principal */  
  #menu ul,
  #menu ul li {
    overflow:visible;
  }

  /* Les rubriques principales s'empilent verticalement sur mobile */ 
  #menu > ul > li.parent {
    float:none;
  }

  /* Définition de la mise en forme des sous-menus et masquage par défaut */
  #menu ul.sousrubrique{
    position: absolute;
    display: none;
    width: 100%;
    border: 1px;
    text-align: center;
  } 

  /* État ouvert du sous-menu après l'ajout de la classe .select */
  #menu ul.sousrubrique.select{
    display: block;
    visibility: visible;
    opacity: 1;
    z-index: 1000;
    transform: translateY(0);
  }

  /* Retire les bordures arrondies héritées de l'ancien thème Blogger aux premiers liens du menu et des sousmenus */
  #menu li.sousmenu > ul li:first-child a,
  #menu > ul > li:first-child > a  {
    border-radius: 0;
  }

  /* Force les tableaux des articles à passer sous les éléments flottants */
  .post-body table {
    clear: both;
  }

}

/* AFFICHAGE SUR PETIT ECRAN mobile (< 768px)*/
@media screen and (max-width : 768px){

  /* Suppression des largeurs fixes héritées par le thème */
  body{
    min-width:0;
    background-position: 45% top;
    background-size: cover;

  }

  /* Masquage des colonnes de droite et de gauche */
  .column-left-outer,
  .column-right-outer,
  .fauxcolumn-left-outer,
  .fauxcolumn-right-outer{
    display:none;
  }

  /* Le conteneur principal s'adapte désormais à la largeur disponible */
  .content-outer,
  .content-fauxcolumn-outer,
  .region-inner {
    min-width: 0 ;
    max-width: 100% ;
  }

  /* Suppression de l'espace occupé par les colonnes de droite et de gauche */
  .main-inner .columns{
    padding-left: 0 ;
    padding-right: 0 ;
  }

  /* L'image du header n'est plus coupée et occupe la place disponible */
  .Header img{
    width: -webkit-fill-available;
    height: 111px;
  }

  /* Mise en forme du bouton menu pour mobile */
  a.menubtn {
    display: inline-block;
    position: relative;
    padding: 0.5em 1.9em;
    text-decoration:none;
    color:#FF4D52;
    margin-top: 1em;
