    overflow: visible;
  }

  /* Mise en forme des liens et préparations du positionnement des indicateurs + / - avec la position: relative */
  #menu li a {
    color: #FF4D52;display: block;
    padding: 0.8em;
    border-bottom: 1px solid #EEE;
    position: relative;
  }

  /* Ajout de l'indicateur + lorsque le menu contenant une sous-menu ne possède pas la classe .select */
  #menu li.sousmenu > a:after {
    content: '+';
    position: absolute;
    top: 0;
    right: 3em;
