    padding-top: 0.9em;
  }

  /* Ajout de l'indicateur - lorsque le menu contenant une sous-menu possède la classe .select */
  #menu li.sousmenu > a.select:after {
    content: "-";
    padding-top: 0.9em;
  }

  /* Le menu contenant un sous-menu qui est sélectionné s'allume pour indiquer à quel menu le sous-menu appartient */
  #menu li.sousmenu > a.select {
